// POWER BI SETTINGS: the settings of this flow only (site, dry run).
// In: any message from an inject node. Out: the same message.
// It reads the site from the Config tab and builds the file paths.
var SITE_NAME = 'Hull';
// true = log row counts, write NO files. false = write the tables.
var DRY_RUN = false;
// Schedule: yesterday plus this many days before it.
var REBUILD_DAYS = 2;
// Folder prefix of the site folder: fact_kpi/<prefix><site>/...
var FOLDER_PREFIX = 'site=';
// First and last date of the calendar table.
var CALENDAR_START = '2026-09-01';
var CALENDAR_END = '2026-12-31';

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}
var matches = shared.sites.filter(function (s) {
  return s.name === SITE_NAME;
});
if (!matches.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'site not in CONFIG'
  });
  node.error('site "' + SITE_NAME + '" is not in the CONFIG sites list');
  return null;
}
var site = matches[0];

var cfg = Object.assign({}, shared);
cfg.site = site.name;
cfg.dayStartHour = site.dayStartHour;
cfg.dryRun = DRY_RUN;
cfg.rebuildDays = REBUILD_DAYS;
cfg.calendarStart = CALENDAR_START;
cfg.calendarEnd = CALENDAR_END;

var root = shared.root;
var folder = FOLDER_PREFIX + site.name;
// YYYY-MM-DD becomes the production day.
cfg.paths = {
  dim_asset: root + '/dim_asset/dim_asset.parquet',
  dim_shift: root + '/dim_shift/dim_shift.parquet',
  fact_kpi: root + '/fact_kpi/' + folder + '/fact_kpi_YYYY-MM-DD.parquet',
  fact_loss: root + '/fact_loss/' + folder + '/fact_loss_YYYY-MM-DD.parquet',
  pbi_plan_opt: root + '/pbi_plan_opt/' + folder +
    '/pbi_plan_opt_YYYY-MM-DD.parquet',
  pbi_time_utilisation: root + '/pbi_time_utilisation/' + folder +
    '/pbi_time_utilisation_YYYY-MM-DD.parquet',
  pbi_daily_losses: root + '/pbi_daily_losses/' + folder +
    '/pbi_daily_losses_YYYY-MM-DD.parquet',
  pbi_machine_names: root + '/pbi_machine_names/' + folder +
    '/pbi_machine_names.parquet',
  pbi_shift_naming: root + '/pbi_shift_naming/' + folder +
    '/pbi_shift_naming.parquet',
  pbi_calendar: root + '/pbi_calendar/pbi_calendar.parquet'
};
flow.set('cfg', cfg);

node.status({
  fill: DRY_RUN ? 'yellow' : 'green',
  shape: 'dot',
  text: SITE_NAME + (DRY_RUN ? ' DRY RUN' : ' WRITE MODE')
});
return msg;

// Builds the list of production days. One message leaves per day, oldest first.
// In: the schedule inject (any payload) or the backfill inject
// {start, end}. Out: {topic: 'day', payload: 'YYYY-MM-DD', mode}.
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var cfg = flow.get('cfg');
// A production day D runs from D start hour to D+1 start hour (UTC).
var PRODUCTION_DAY_START_HOURS = cfg.dayStartHour;
var p = msg.payload;
var days = [];
var mode;

function dayStr(ms) {
  return new Date(ms).toISOString().slice(0, 10);
}

if (p && typeof p === 'object' && p.start && p.end) {
  mode = 'backfill';
  var s = Date.parse(p.start + 'T00:00:00Z');
  var e = Date.parse(p.end + 'T00:00:00Z');
  if (isNaN(s) || isNaN(e) || e < s) {
    node.error(
      'Backfill needs {"start":"YYYY-MM-DD","end":"YYYY-MM-DD"} ' +
        'with start <= end',
      msg
    );
    return null;
  }
  for (var t = s; t <= e; t += DAY_MS) {
    days.push(dayStr(t));
  }
} else {
  mode = 'schedule';
  var now = Date.now();
  // One hour after the day start the latest finished production day is the
  // one before the current one.
  var shifted = now - PRODUCTION_DAY_START_HOURS * HOUR_MS - DAY_MS;
  var latest = Date.parse(dayStr(shifted) + 'T00:00:00Z');
  for (var i = cfg.rebuildDays; i >= 0; i--) {
    days.push(dayStr(latest - i * DAY_MS));
  }
}

var text = mode + ': ' + days.length + ' day(s) ' + days[0];
if (days.length > 1) {
  text += ' .. ' + days[days.length - 1];
}
node.status({ fill: 'blue', shape: 'dot', text: text });
var messages = days.map(function (d) {
  return { topic: 'day', payload: d, mode: mode };
});
return [messages];

// Builds the pbi_calendar table: one row per date, Monday week start.
// In: any message after the settings node. Out 1: msg.payload = the rows
// (topic pbi_calendar). Out 2: a log line. Dry run sends only the log line.
var DAY_MS = 86400000;
var cfg = flow.get('cfg');
var MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December'
];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}

// ISO week number (Monday start, week 1 holds the first Thursday).
function isoWeek(ms) {
  var d = new Date(ms);
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  var yearStart = Date.UTC(d.getUTCFullYear(), 0, 1);
  return Math.ceil(((d.getTime() - yearStart) / DAY_MS + 1) / 7);
}

var rows = [];
var start = Date.parse(cfg.calendarStart + 'T00:00:00Z');
var end = Date.parse(cfg.calendarEnd + 'T00:00:00Z');
for (var t = start; t <= end; t += DAY_MS) {
  var d = new Date(t);
  var month = d.getUTCMonth();
  var year = d.getUTCFullYear();
  var quarter = Math.floor(month / 3) + 1;
  var mondayOffset = (d.getUTCDay() + 6) % 7;
  rows.push({
    date: d.toISOString().slice(0, 10),
    year: year,
    month_number: month + 1,
    month: MONTHS[month],
    month_short_name: MONTHS[month].slice(0, 3),
    month_year: MONTHS[month].slice(0, 3) + ' ' + year,
    month_year_number: pad(month + 1) + ' ' + String(year).slice(2),
    quarter: 'QTR' + quarter,
    quarter_number: quarter,
    week_number: isoWeek(t),
    week_start: new Date(t - mondayOffset * DAY_MS).toISOString().slice(0, 10)
  });
}

var text = 'pbi_calendar ' + rows.length + ' rows';
if (cfg.dryRun) {
  var line = {
    topic: 'log',
    payload: 'calendar [setup] DRY RUN: ' + text
  };
  return [null, line];
}
var table = {
  topic: 'pbi_calendar',
  day: '',
  payload: rows
};
return [table, null];

// Starts one day: sets the path of the first file to read.
// In: msg.payload = the production day (YYYY-MM-DD) from the day list.
// Out: msg.day, msg.path = dim_asset file, msg.tables = {} (filled later).
// msg.topic = the day, so the join after each parquet read keeps days apart.
var cfg = flow.get('cfg');
msg.day = msg.payload;
msg.topic = msg.day;
msg.tables = {};
msg.path = cfg.paths.dim_asset.replace('YYYY-MM-DD', msg.day);
delete msg.payload;
return msg;

// Keeps the rows that were just read and sets the next file to read.
// In: msg.payload = the rows (from the join after the parquet read node).
// Out: msg.tables.dim_asset = the rows, msg.path = the file of dim_shift.
var KEEP = 'dim_asset';
var NEXT = 'dim_shift';
var cfg = flow.get('cfg');
// The join before this node gives a list of rows. If the parquet node
// already sent a list per file, the join gives a list of lists: flatten it.
var rows = msg.payload;
if (Array.isArray(rows) && rows.length && Array.isArray(rows[0])) {
  rows = [].concat.apply([], rows);
}
if (!Array.isArray(rows)) {
  node.error(KEEP + ': the file did not give a list of rows', msg);
  return null;
}
msg.tables[KEEP] = rows;
delete msg.payload;
if (NEXT) {
  msg.path = cfg.paths[NEXT].replace('YYYY-MM-DD', msg.day);
}
return msg;

// Keeps the rows that were just read and sets the next file to read.
// In: msg.payload = the rows (from the join after the parquet read node).
// Out: msg.tables.dim_shift = the rows, msg.path = the file of fact_kpi.
var KEEP = 'dim_shift';
var NEXT = 'fact_kpi';
var cfg = flow.get('cfg');
// The join before this node gives a list of rows. If the parquet node
// already sent a list per file, the join gives a list of lists: flatten it.
var rows = msg.payload;
if (Array.isArray(rows) && rows.length && Array.isArray(rows[0])) {
  rows = [].concat.apply([], rows);
}
if (!Array.isArray(rows)) {
  node.error(KEEP + ': the file did not give a list of rows', msg);
  return null;
}
msg.tables[KEEP] = rows;
delete msg.payload;
if (NEXT) {
  msg.path = cfg.paths[NEXT].replace('YYYY-MM-DD', msg.day);
}
return msg;

// Keeps the rows that were just read and sets the next file to read.
// In: msg.payload = the rows (from the join after the parquet read node).
// Out: msg.tables.fact_kpi = the rows, msg.path = the file of fact_loss.
var KEEP = 'fact_kpi';
var NEXT = 'fact_loss';
var cfg = flow.get('cfg');
// The join before this node gives a list of rows. If the parquet node
// already sent a list per file, the join gives a list of lists: flatten it.
var rows = msg.payload;
if (Array.isArray(rows) && rows.length && Array.isArray(rows[0])) {
  rows = [].concat.apply([], rows);
}
if (!Array.isArray(rows)) {
  node.error(KEEP + ': the file did not give a list of rows', msg);
  return null;
}
msg.tables[KEEP] = rows;
delete msg.payload;
if (NEXT) {
  msg.path = cfg.paths[NEXT].replace('YYYY-MM-DD', msg.day);
}
return msg;

// Keeps the rows that were just read and sets the next file to read.
// In: msg.payload = the rows (from the join after the parquet read node).
// Out: msg.tables.fact_loss = the rows, msg.path = the file of .
var KEEP = 'fact_loss';
var NEXT = '';
var cfg = flow.get('cfg');
// The join before this node gives a list of rows. If the parquet node
// already sent a list per file, the join gives a list of lists: flatten it.
var rows = msg.payload;
if (Array.isArray(rows) && rows.length && Array.isArray(rows[0])) {
  rows = [].concat.apply([], rows);
}
if (!Array.isArray(rows)) {
  node.error(KEEP + ': the file did not give a list of rows', msg);
  return null;
}
msg.tables[KEEP] = rows;
delete msg.payload;
if (NEXT) {
  msg.path = cfg.paths[NEXT].replace('YYYY-MM-DD', msg.day);
}
return msg;

// Builds the pbi_plan_opt and pbi_time_utilisation rows of one day.
// In: msg.tables (dim_asset, dim_shift, fact_kpi). Out: msg.planRows
// (machine x day x shift) and msg.utilRows (machine x day).
var MIN_MS = 60000;
var DAY_MS = 86400000;
var MINUTES_PER_DAY = 1440;
var loadedAt = Date.now();

function toMs(value) {
  return typeof value === 'number' ? value : Date.parse(value);
}

var calendarOf = {};
msg.tables.dim_asset.forEach(function (a) {
  calendarOf[a.asset_id] = a.calendar_id;
});

// The shift of an instant: the calendar event whose recurrence covers it.
function shiftOf(calendarId, ms) {
  var found = null;
  msg.tables.dim_shift.forEach(function (e) {
    if (found || e.calendar_id !== calendarId) {
      return;
    }
    var days = e.freq === 'WEEKLY' ? 7 : e.freq === 'DAILY' ? 1 : 0;
    var start = toMs(e.start_utc);
    var until = e.until_utc ? toMs(e.until_utc) : Infinity;
    if (!days || ms < start || ms > until) {
      return;
    }
    var step = days * e.interval * DAY_MS;
    var occurrence = start + Math.floor((ms - start) / step) * step;
    if (ms < occurrence + e.duration_ms) {
      found = e.shift_name;
    }
  });
  return found;
}

// Adds a value to a sum; a sum with no value at all stays null.
function addTo(sum, key, value) {
  if (value === null || value === undefined) {
    return;
  }
  sum[key] = (sum[key] || 0) + value;
}

function minutes(ms) {
  return ms === null || ms === undefined ? null : ms / MIN_MS;
}

var groups = {};
msg.tables.fact_kpi.forEach(function (k) {
  var shift = shiftOf(calendarOf[k.asset_id], toMs(k.period_start));
  var key = k.asset_id + '|' + k.production_day + '|' + shift;
  var g = groups[key];
  if (!g) {
    g = {
      first: k,
      shift: shift,
      sum: {},
      hours: 0
    };
    groups[key] = g;
  }
  g.hours += 1;
  addTo(g.sum, 'good', k.good_parts);
  var planned = k.planned_stop_shift_plan_ms;
  if (k.total_time_ms !== null && planned !== null) {
    addTo(g.sum, 'total', minutes(k.total_time_ms - planned));
  }
  addTo(g.sum, 'opt', minutes(k.operational_time_ms));
  addTo(g.sum, 'oee', minutes(k.used_operational_time_ms));
});

function sumOrNull(sum, key) {
  return sum[key] === undefined ? null : sum[key];
}

var planRows = [];
var utilByMachine = {};
Object.keys(groups).forEach(function (key) {
  var g = groups[key];
  var k = g.first;
  planRows.push({
    site_name: k.site,
    area_name: k.area,
    machine_name: k.asset_name,
    unique_machine_name: k.asset_id,
    date: k.production_day,
    shift_name: g.shift,
    part_name: null,
    product_key: null,
    good_parts: sumOrNull(g.sum, 'good'),
    capacity: null,
    downtime_units: null,
    total_time: sumOrNull(g.sum, 'total'),
    planned_opt: sumOrNull(g.sum, 'opt'),
    oee_time: sumOrNull(g.sum, 'oee'),
    oee_target: null,
    pdt_target: null,
    updt_target: null,
    source_hours: g.hours,
    loaded_at: loadedAt
  });
  var u = utilByMachine[k.asset_id];
  if (!u) {
    u = { first: k, sum: {} };
    utilByMachine[k.asset_id] = u;
  }
  addTo(u.sum, 'total', g.sum.total);
  addTo(u.sum, 'opt', g.sum.opt);
  addTo(u.sum, 'oee', g.sum.oee);
});

var utilRows = Object.keys(utilByMachine).map(function (id) {
  var k = utilByMachine[id].first;
  var sum = utilByMachine[id].sum;
  return {
    site_name: k.site,
    machine_name: k.asset_name,
    unique_machine_name: k.asset_id,
    date: k.production_day,
    total_time_total: sumOrNull(sum, 'total'),
    planned_opt_total: sumOrNull(sum, 'opt'),
    oee_time_total: sumOrNull(sum, 'oee'),
    all_time: MINUTES_PER_DAY,
    loaded_at: loadedAt
  };
});

msg.planRows = planRows;
msg.utilRows = utilRows;
return msg;

// Builds the pbi_daily_losses rows of one day, one row per stop.
// In: msg.tables (dim_asset, dim_shift, fact_loss). Out: msg.lossRows.
// Columns without data in Insights Hub (units, targets, product) are null.
var MIN_MS = 60000;
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var cfg = flow.get('cfg');
// The reason a stop gets when nobody chose one.
var DEFAULT_REASON = 'Unplanned Downtime';
var BREAKDOWN_CATEGORY = 'Breakdown';
var loadedAt = Date.now();

function toMs(value) {
  return typeof value === 'number' ? value : Date.parse(value);
}

var calendarOf = {};
msg.tables.dim_asset.forEach(function (a) {
  calendarOf[a.asset_id] = a.calendar_id;
});

// Same rule as in 3.1: which calendar event covers the instant.
function shiftOf(calendarId, ms) {
  var found = null;
  msg.tables.dim_shift.forEach(function (e) {
    if (found || e.calendar_id !== calendarId) {
      return;
    }
    var days = e.freq === 'WEEKLY' ? 7 : e.freq === 'DAILY' ? 1 : 0;
    var start = toMs(e.start_utc);
    var until = e.until_utc ? toMs(e.until_utc) : Infinity;
    if (!days || ms < start || ms > until) {
      return;
    }
    var step = days * e.interval * DAY_MS;
    var occurrence = start + Math.floor((ms - start) / step) * step;
    if (ms < occurrence + e.duration_ms) {
      found = e.shift_name;
    }
  });
  return found;
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, month) {
  var d = new Date(Date.UTC(year, month + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// Europe/London offset in hours (UK sites only).
function londonOffsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var inBst = ms >= lastSundayUtc(year, 2) && ms < lastSundayUtc(year, 9);
  return inBst ? 1 : 0;
}

function lossGroup(row) {
  if (cfg.plannedRoots.indexOf(row.reason_category) >= 0) {
    return 'Planned Loss';
  }
  if (row.reason === DEFAULT_REASON) {
    return 'Not Logged';
  }
  return 'Unplanned Loss';
}

msg.lossRows = msg.tables.fact_loss.map(function (r) {
  var startMs = toMs(r.event_start);
  var localIso = new Date(startMs + londonOffsetHours(startMs) * HOUR_MS)
    .toISOString();
  var month = r.local_date.slice(0, 7);
  var isBreakdown = r.reason_category === BREAKDOWN_CATEGORY;
  return {
    site_name: r.site,
    machine_name: r.asset_name,
    unique_machine_name: r.asset_id,
    date: r.local_date,
    time: localIso.slice(11, 19),
    shift_start_date: r.production_day,
    shift_name: shiftOf(calendarOf[r.asset_id], startMs),
    duration: r.duration_ms / MIN_MS,
    loss_units: null,
    loss_lvl3_group: lossGroup(r),
    loss_lvl3_sub_group: r.reason_category,
    loss_lvl3_desc: r.reason,
    loss_final_level: r.reason,
    equipment: r.reason_subgroup,
    breakdown_types: isBreakdown ? r.reason_subgroup : null,
    batch_id: null,
    comment_count: r.comment_count,
    part_name: null,
    product_key: null,
    loss_target_key: r.line + '|' + r.reason_category + '|' + month,
    value: null,
    target: null,
    volume_key: r.line + '|' + month,
    volume_total: null,
    loaded_at: loadedAt
  };
});
return msg;

// Builds one message per table for the parquet nodes.
// In: msg.planRows, utilRows, lossRows and msg.tables. Out 1 to 5: the
// five day tables. Out 6: log line. Dry run writes nothing, only the log.
var day = msg.day;
var cfg = flow.get('cfg');

// Machine names: the assets of this site, from dim_asset.
var machines = msg.tables.dim_asset.filter(function (a) {
  return a.site === cfg.site;
}).map(function (a) {
  return {
    site_name: a.site,
    area: a.area,
    dept: a.area,
    machine_name: a.asset_name,
    product_type: null,
    unique_machine_name: a.asset_id,
    loaded_at: Date.now()
  };
});

// Shift names: the distinct shift names of the calendars of this site.
var calendars = {};
msg.tables.dim_asset.forEach(function (a) {
  if (a.site === cfg.site) {
    calendars[a.calendar_id] = true;
  }
});
var seen = {};
var shifts = [];
msg.tables.dim_shift.forEach(function (s) {
  if (calendars[s.calendar_id] && !seen[s.shift_name]) {
    seen[s.shift_name] = true;
    shifts.push({ shift: s.shift_name, loaded_at: Date.now() });
  }
});

var counts = 'plan ' + msg.planRows.length +
  ', util ' + msg.utilRows.length +
  ', losses ' + msg.lossRows.length +
  ', machines ' + machines.length +
  ', shifts ' + shifts.length;
if (cfg.dryRun) {
  var dry = {
    topic: 'log',
    payload: day + ' [pbi] DRY RUN: ' + counts
  };
  return [null, null, null, null, null, dry];
}

function table(name, rows) {
  if (!rows.length) {
    return null;
  }
  return { topic: name, day: day, payload: rows };
}
var line = {
  topic: 'log',
  payload: day + ' [pbi] WRITING ' + counts
};
return [
  table('pbi_plan_opt', msg.planRows),
  table('pbi_time_utilisation', msg.utilRows),
  table('pbi_daily_losses', msg.lossRows),
  table('pbi_machine_names', machines),
  table('pbi_shift_naming', shifts),
  line
];

// Sets the file path in the data lake for the table pbi_plan_opt.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_plan_opt.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake for the table pbi_time_utilisation.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_time_utilisation.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake for the table pbi_daily_losses.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_daily_losses.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake for the table pbi_machine_names.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_machine_names.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake for the table pbi_shift_naming.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_shift_naming.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake for the table pbi_calendar.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The text YYYY-MM-DD
// in the path becomes the production day, so a rerun replaces the file.
var cfg = flow.get('cfg');
msg.path = cfg.paths.pbi_calendar.replace('YYYY-MM-DD', msg.day);
msg.filename = msg.path.split('/').pop();
return msg;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'powerbi';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'powerbi';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
